class Solution {
public:
    int mergeSort(vector<int>& nums, int lo, int hi) {
        if (lo >= hi) return 0;
        int mid = lo + (hi - lo) / 2;
        int cnt = mergeSort(nums, lo, mid) + mergeSort(nums, mid + 1, hi);
        // Count cross pairs: i in [lo, mid], j in [mid+1, hi].
        // Both halves are sorted, so j only moves forward.
        int j = mid + 1;
        for (int i = lo; i <= mid; i++) {
            while (j <= hi && (long long)nums[i] > 2LL * nums[j]) j++;
            cnt += j - (mid + 1);
        }
        // Merge the two sorted halves in place.
        vector<int> tmp;
        tmp.reserve(hi - lo + 1);
        int a = lo, b = mid + 1;
        while (a <= mid && b <= hi) {
            if (nums[a] <= nums[b]) tmp.push_back(nums[a++]);
            else tmp.push_back(nums[b++]);
        }
        while (a <= mid) tmp.push_back(nums[a++]);
        while (b <= hi) tmp.push_back(nums[b++]);
        for (int t = 0; t < (int)tmp.size(); t++) nums[lo + t] = tmp[t];
        return cnt;
    }
    int reversePairs(vector<int>& nums) {
        if (nums.empty()) return 0;
        return mergeSort(nums, 0, (int)nums.size() - 1);
    }
};
